#include "edgeshield/http_server.hpp"
#include "edgeshield/detectors.hpp"
#include "edgeshield/system_monitor.hpp"
#include "edgeshield/pcap_reader.hpp"
#include <iostream>
#include <string>
int main(int argc,char**argv){std::string mode=argc>1?argv[1]:"serve";if(mode=="serve"){int port=argc>2?std::stoi(argv[2]):8080;std::string host=argc>3?argv[3]:"127.0.0.1";return edgeshield::HttpServer(port,host).run();}if(mode=="pcap"){if(argc<3){std::cerr<<"PCAP path required\n";return 2;}try{auto p=edgeshield::PcapReader{}.read_ethernet_ipv4(argv[2]);std::cout<<"packets_seen="<<p.packets_seen<<" flows="<<p.flows.size()<<"\n";for(const auto&f:p.flows){auto r=edgeshield::NetworkDetector{}.analyze(f);std::cout<<f.src_ip<<':'<<f.src_port<<" -> "<<f.dst_ip<<':'<<f.dst_port<<" proto="<<f.protocol<<" packets="<<f.packets<<" bytes="<<f.bytes<<" flagged="<<r.flagged<<" risk="<<r.event.risk_score<<"\n";}return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}if(mode=="monitor"){auto m=edgeshield::SystemMonitor{}.sample();std::cout<<"CPU="<<(m.cpu_utilisation_percent?std::to_string(*m.cpu_utilisation_percent):"N/A")<<"%\nRAM total="<<(m.memory_total_kb?std::to_string(*m.memory_total_kb):"N/A")<<" kB\nRAM available="<<(m.memory_available_kb?std::to_string(*m.memory_available_kb):"N/A")<<" kB\nDisk="<<(m.root_storage_utilisation_percent?std::to_string(*m.root_storage_utilisation_percent):"N/A")<<"%\nTemp="<<(m.cpu_temperature_celsius?std::to_string(*m.cpu_temperature_celsius):"N/A")<<" C\n";return 0;}if(mode=="url"||mode=="sms"){if(argc<3){std::cerr<<"Input required\n";return 2;}auto r=mode=="url"?edgeshield::UrlDetector{}.analyze(argv[2]):edgeshield::SmsDetector{}.analyze(argv[2]);std::cout<<"flagged="<<r.flagged<<" risk="<<r.event.risk_score<<" heuristic_strength="<<r.event.confidence<<" evidence="<<r.event.evidence.size()<<"\n";for(const auto&e:r.event.evidence)std::cout<<"- "<<e.key<<": "<<e.value<<" — "<<e.explanation<<"\n";return 0;}std::cerr<<"Usage: edgeshieldd [serve [port] [bind-ip]|monitor|pcap <file.pcap>|url <text>|sms <text>]\n";return 2;}
